// ─── File: CapacityPlannerDemo.java ───
// Applies Little's Law (concurrency = throughput * latency) then sizes
// threads, instances, and the DB connection pool with safety headroom.
import java.util.logging.*;

public class CapacityPlannerDemo {
    private static final Logger log = Logger.getLogger("CAP");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Measured profile for the payments endpoint.
        WorkloadProfile payments = new WorkloadProfile(
                1000,   // target TPS
                200,    // avg latency ms
                180,    // wait ms (I/O)
                20,     // compute ms (CPU)
                50);    // db connection hold ms
        DatabaseLimits db = new DatabaseLimits(100);
        CapacityCalculator calc = new CapacityCalculator(4, 0.70, 2);

        int concurrency = calc.requiredConcurrency(payments);
        int threads = calc.threadsPerInstance(payments);
        int instances = calc.instanceCount(concurrency, threads);
        int poolPerPod = calc.connectionPoolPerPod(payments, instances, db);

        log.info(() -> "Required concurrency (Little's Law) = " + concurrency + " in-flight payments");
        log.info(() -> "Useful threads per instance = " + threads);
        log.info(() -> "Instances needed (with utilization + redundancy) = " + instances);
        log.info(() -> "DB connections per pod = " + poolPerPod
                + " (fleet total = " + (poolPerPod * instances) + ", ceiling = " + db.maxConnections() + ")");

        new SizingReport(payments, concurrency, threads, instances, poolPerPod, db).print();
    }
}

// ─── model/WorkloadProfile.java ───
class WorkloadProfile {
    private final int tps, latencyMs, waitMs, computeMs, dbHoldMs;
    WorkloadProfile(int tps, int latencyMs, int waitMs, int computeMs, int dbHoldMs) {
            this.tps = tps;
            this.latencyMs = latencyMs
            this.waitMs = waitMs;
            this.computeMs = computeMs;
            this.dbHoldMs = dbHoldMs;
    }
    int tps() { return tps; }
    double latencySec() { return latencyMs / 1000.0; }
    double dbHoldSec() { return dbHoldMs / 1000.0; }
    int waitMs() { return waitMs; }
    int computeMs() { return computeMs; }
}

// ─── model/DatabaseLimits.java ───
class DatabaseLimits {
    private final int maxConnections;
    DatabaseLimits(int maxConnections) { this.maxConnections = maxConnections; }
    int maxConnections() { return maxConnections; }
}

// ─── calc/CapacityCalculator.java ───
class CapacityCalculator {
    private final int cores; private final double utilization; private final int redundancy;
    CapacityCalculator(int cores, double utilization, int redundancy) {
            this.cores = cores;
            this.utilization = utilization
            this.redundancy = redundancy;
    }
    // Little's Law: concurrency = throughput * latency.
    int requiredConcurrency(WorkloadProfile w) {
        return (int) Math.ceil(w.tps() * w.latencySec());
    }
    // threads = cores * utilization * (1 + wait/compute). I/O-bound → many useful threads.
    int threadsPerInstance(WorkloadProfile w) {
        double ratio = 1.0 + ((double) w.waitMs() / w.computeMs());
        return (int) Math.floor(cores * utilization * ratio);
    }
    // instances = ceil(concurrency / threadsPerInstance / utilization) + redundancy.
    int instanceCount(int concurrency, int threadsPerInstance) {
        int steady = (int) Math.ceil(concurrency / (double) threadsPerInstance / utilization);
        return steady + redundancy;
    }
    // Fleet pool by Little's Law: tps * dbHold; per pod = fleet / instances, capped by ceiling.
    int connectionPoolPerPod(WorkloadProfile w, int instances, DatabaseLimits db) {
        int fleetConnections = (int) Math.ceil(w.tps() * w.dbHoldSec());
        int perPod = (int) Math.ceil(fleetConnections / (double) instances);
        // Guard: never let pods * perPod exceed the DB ceiling.
        int maxPerPod = db.maxConnections() / instances;
        return Math.min(perPod, Math.max(1, maxPerPod));
    }
}

// ─── report/SizingReport.java ───
class SizingReport {
    private static final Logger log = Logger.getLogger("CAP");
    private final WorkloadProfile w; private final int concurrency, threads, instances, poolPerPod;
    private final DatabaseLimits db;
    SizingReport(WorkloadProfile w, int concurrency, int threads, int instances, int poolPerPod, DatabaseLimits db) {
            this.w = w;
            this.concurrency = concurrency
            this.threads = threads;
            this.instances = instances;
            this.poolPerPod = poolPerPod
            this.db = db;
    }
    void print() {
        log.info("──── SIZING RECOMMENDATION ────");
        log.info(() -> "Target: " + w.tps() + " TPS @ " + (int)(w.latencySec()*1000) + "ms latency");
        log.info(() -> "Run " + instances + " pods, each ~" + threads + " worker threads, pool=" + poolPerPod);
        log.info(() -> "Validate with a load test ramping to " + w.tps()
                + " TPS; watch P99 latency, errors, pool saturation; autoscale on CPU/in-flight.");
    }
}

